        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = 'd69d4e39-99a7-42f9-9dad-36a680c8e2cd'
        AND charge_id = 1047203;
   
    RETURN;
END IF;

END IF;

